### React 集成

```tsx
import "@calenderjs/calendar";
import { useRef, useEffect } from "react";

function CalendarApp({ events, user, runtime }) {
  const ref = useRef<HTMLElement>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.events = events;
    el.user = user;
    el.eventRuntime = runtime;
